return {api_version=1,id="EX1_084", rarity = "free",name="Warsong Commander",text="Whenever you summon a minion with 3 or less Attack, give it <b>Charge</b>.",set="LEGACY",type="minion",class="warrior",cost=3,attack=2,health=3,triggers={{event="minion_summoned",timing="after",active_zones={"board"},condition=function(ctx,self,e)return e.player==ctx:controller(self)and ctx:entity(e.entity).attack<=3 end,effect=function(ctx,self,e)cardlib.effects.grant_keyword(ctx, e.entity,"charge")end}}}
